"use strict";

// Fixed native preload. These values are generated by the restricted executor,
// never by renderer input, command output or the repository. The operating
// system continues to enforce all ordinary TCP/network restrictions.
const net = require("node:net");
const http = require("node:http");
const portText = process.env.MIVLET_PREVIEW_PORT;
const pipe = process.env.MIVLET_PREVIEW_PIPE;
if (!/^[1-9][0-9]{0,4}$/.test(portText || "") || Number(portText) > 65535 ||
    !/^\\\\\.\\pipe\\LOCAL\\MivletPreview-[a-f0-9]{48}$/.test(pipe || "")) {
  throw new Error("The native preview transport is unavailable.");
}
const port = Number(portText);
const listen = net.Server.prototype.listen;
const address = net.Server.prototype.address;
const redirected = new WeakSet();

function requestedPort(args) {
  const first = args[0];
  const value = first && typeof first === "object" ? first.port : first;
  if (typeof value === "number" && Number.isInteger(value)) return value;
  if (typeof value === "string" && /^[0-9]{1,5}$/.test(value)) return Number(value);
  return null;
}

Object.defineProperty(net.Server.prototype, "listen", {
  configurable: true,
  writable: true,
  value: function (...args) {
    if (!(this instanceof http.Server) || requestedPort(args) !== port) {
      return Reflect.apply(listen, this, args);
    }
    const callback = typeof args.at(-1) === "function" ? args.at(-1) : undefined;
    const options = { path: pipe, exclusive: true, readableAll: false, writableAll: false };
    redirected.add(this);
    // There is one path and one attempt. Never fall back to a host TCP port.
    return Reflect.apply(listen, this, callback ? [options, callback] : [options]);
  }
});
Object.defineProperty(net.Server.prototype, "address", {
  configurable: true,
  writable: true,
  value: function () {
    const actual = Reflect.apply(address, this, []);
    if (!redirected.has(this) || actual === null) return actual;
    // Frameworks may use address() to build their client/HMR URLs. This is
    // metadata only: no TCP listener or sandbox loopback grant exists.
    return { address: "127.0.0.1", family: "IPv4", port };
  }
});

// Optional, bounded picker bootstrap. Preserve application CSP and compression:
// if a normal first HTML chunk cannot be instrumented, the preview still works
// and the UI receives no picker-ready signal. No script policy is bypassed.
const emit = http.Server.prototype.emit;
Object.defineProperty(http.Server.prototype, "emit", {
  configurable: true,
  writable: true,
  value: function (event, ...args) {
    if (event === "request" && redirected.has(this) && args[1]) {
      const response = args[1];
      let inspected = false;
      for (const method of ["write", "end"]) {
        const original = response[method];
        response[method] = function (...values) {
          const chunk = values[0];
          if (!inspected && (typeof chunk === "string" || Buffer.isBuffer(chunk)) && chunk.length > 0) {
            inspected = true;
            const html = String(response.getHeader("content-type") || "").toLowerCase().includes("text/html");
            if (html && !response.headersSent && !response.getHeader("content-encoding")) {
              const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, typeof values[1] === "string" ? values[1] : "utf8");
              if (bytes.length <= 65536) {
                const lower = bytes.toString("latin1").toLowerCase();
                const head = lower.indexOf("<head");
                const end = head < 0 ? -1 : lower.indexOf(">", head);
                if (end >= 0) {
                  const script = Buffer.from('<script defer src="/__mivlet_preview/picker.js"></script>');
                  response.removeHeader("content-length");
                  response.removeHeader("etag");
                  values[0] = Buffer.concat([bytes.subarray(0, end + 1), script, bytes.subarray(end + 1)]);
                }
              }
            }
          }
          return Reflect.apply(original, this, values);
        };
      }
    }
    return Reflect.apply(emit, this, [event, ...args]);
  }
});
